// Ported from the Node app's Sequelize model Incident (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class IncidentConfiguration : IEntityTypeConfiguration<Incident>
{
    public void Configure(EntityTypeBuilder<Incident> builder)
    {
        builder.ToTable("incidents", t =>
        {
            t.HasCheckConstraint("CK_incidents_severity", "[severity] IN (N'minor', N'moderate', N'serious')");
            t.HasCheckConstraint("CK_incidents_status", "[status] IN (N'open', N'resolved')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.IncidentDate).HasColumnName("incident_date").HasColumnType("date");
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.Location).HasColumnName("location").HasColumnType("nvarchar(120)").HasMaxLength(120);
        builder.Property(e => e.Severity).HasColumnName("severity").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'minor'");
        builder.Property(e => e.Description).HasColumnName("description").HasColumnType("nvarchar(500)").HasMaxLength(500).IsRequired();
        builder.Property(e => e.ActionTaken).HasColumnName("action_taken").HasColumnType("nvarchar(500)").HasMaxLength(500);
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'open'");
        builder.HasOne(e => e.Student).WithMany(p => p.Incidents).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
